   u1 = sqrt(a*a+b*b);
   if (u1>RADCURVMUL4) return(INFINITY);
   theta = my_atan2(b,a);
   alpha = acos(u1/RADCURVMUL4);
   t = mod2pi(MPIDIV2 + alpha + theta);
   u = mod2pi(MPI-2*alpha);

