    ret.factor = 1.0f / (float)M_PI;
    ret.symbol = "pi";
}else if( std::abs(tick/M_SQRT2 - floor(tick/M_SQRT2)) < eps ) {
    ret.factor = 1.0f / (float)M_SQRT2;
    ret.symbol = "\251 2";
}else if( std::abs(tick/M_E - floor(tick/M_E)) < eps ) {
    ret.factor = 1.0f / (float)M_E;
    ret.symbol = "e";

