{
	vector_map::Point error;
	error.pid = -1;

	for (const vector_map::Node& n : vmap.nodes) {
		if (n.nid != lane.fnid)
			continue;
		for (const vector_map::Point& p : vmap.points) {
			if (p.pid != n.pid)
				continue;
			return p;
		}
