  if (line.lid == 0)
    return marker;

  Point bp = vmap.findByKey(Key<Point>(line.bpid));
  if (bp.pid == 0)
    return marker;

  Point fp = vmap.findByKey(Key<Point>(line.fpid));
  if (fp.pid == 0)
