  marker.points.push_back(convertPointToGeomPoint(fp));

  marker.scale.x = MAKER_SCALE_LINE;
  marker.color = createColorRGBA(color);
  if (marker.color.a == COLOR_VALUE_MIN)
    return marker;

  enableMarker(marker);
  return marker;
}

