/* for area.csv */
struct AreaClass {
  int aid;
  int slid;
  int elid;

#define MIP_3DM_COMMAND_SET 0x0C
//////////////////////////////////////////////////////////////////////////////// // 3DM COMMAND DESCRIPTORS (command desc are < 0x80) ////////////////////////////////////////////////////////////////////////////////
#define MIP_3DM_CMD_POLL_AHRS_MESSAGE 0x01 #define MIP_3DM_CMD_POLL_GPS_MESSAGE 0x02 #define MIP_3DM_CMD_POLL_NAV_MESSAGE 0x03 #define MIP_3DM_CMD_GET_AHRS_BASE_RATE 0x06 #define MIP_3DM_CMD_GET_GPS_BASE_RATE 0x07 #define MIP_3DM_CMD_AHRS_MESSAGE_FORMAT 0x08 #define MIP_3DM_CMD_GPS_MESSAGE_FORMAT 0x09 #define MIP_3DM_CMD_NAV_MESSAGE_FORMAT 0x0A #define MIP_3DM_CMD_GET_NAV_BASE_RATE 0x0B #define MIP_3DM_CMD_CONTROL_DATA_STREAM 0x11 #define MIP_3DM_CMD_RAW_RTCM_2_3_MESSAGE 0x20 #define MIP_3DM_CMD_SAVE_DEVICE_SETTINGS 0x30 #define MIP_3DM_CMD_SET_GPS_DYNAMICS_MODE 0x34 #define MIP_3DM_CMD_SET_AHRS_SIGNAL_COND 0x35 #define MIP_3DM_CMD_SET_AHRS_TIMESTAMP 0x36 #define MIP_3DM_CMD_ACCEL_BIAS 0x37 #define MIP_3DM_CMD_GYRO_BIAS 0x38 #define MIP_3DM_CMD_CAPTURE_GYRO_BIAS 0x39 #define MIP_3DM_CMD_HARD_IRON_VECTOR 0x3A #define MIP_3DM_CMD_SOFT_IRON_MATRIX 0x3B #define MIP_3DM_CDM_CONING_AND_SCULLING_ENABLE 0x3E #define MIP_3DM_CDM_SENSOR2VEHICLE_TRANSFORMATION 0x3F #define MIP_3DM_CMD_UART_BAUDRATE 0x40 #define MIP_3DM_CMD_LOW_PASS_FILTER_SETTINGS 0x50 #define MIP_3DM_CMD_COMPLEMENTARY_FILTER 0x51

        camerapoints=camerapoints*invR.t()+cv::Mat::ones(m,1,CV_64F)*invT.t();
        std::vector<cv::Point2d> planepoints;
        planepoints.resize(m);
        for(j=0;j<m;j++)
        {
            double tmpx=camerapoints.at<double>(j,0)/camerapoints.at<double>(j,2);
            double tmpy=camerapoints.at<double>(j,1)/camerapoints.at<double>(j,2);
            double r2=tmpx*tmpx+tmpy*tmpy;
            double tmpdist=1+distcoeff.at<double>(0)*r2+distcoeff.at<double>(1)*r2*r2+distcoeff.at<double>(4)*r2*r2*r2;
            planepoints[j].x=tmpx*tmpdist+2*distcoeff.at<double>(2)*tmpx*tmpy+distcoeff.at<double>(3)*(r2+2*tmpx*tmpx);
            planepoints[j].y=tmpy*tmpdist+distcoeff.at<double>(2)*(r2+2*tmpy*tmpy)+2*distcoeff.at<double>(3)*tmpx*tmpy;
            planepoints[j].x=cameramat.at<double>(0,0)*planepoints[j].x+cameramat.at<double>(0,2);
            planepoints[j].y=cameramat.at<double>(1,1)*planepoints[j].y+cameramat.at<double>(1,2);
            cv::circle(tmpimage,planepoints[j],2,cv::Scalar(0,0,255));
        }
        if(tmpimage.type()==CV_8UC3)
        {
            QImage img(tmpimage.data, tmpimage.cols, tmpimage.rows, tmpimage.step, QImage::Format_RGB888);
            img=img.rgbSwapped();
            QScrollArea * scrollarea=(QScrollArea *)(calibimagesshow->widget(i));
            QLabel * tmpcalibimageshow=(QLabel *)(scrollarea->widget());
            tmpcalibimageshow->setPixmap(QPixmap::fromImage(img));
        }
        else if(tmpimage.type()==CV_8UC1)
        {
            QImage img(tmpimage.data, tmpimage.cols, tmpimage.rows, tmpimage.step, QImage::Format_Indexed8);
            img.setColorTable(colorTable);
            QScrollArea * scrollarea=(QScrollArea *)(calibimagesshow->widget(i));
            QLabel * tmpcalibimageshow=(QLabel *)(scrollarea->widget());
            tmpcalibimageshow->setPixmap(QPixmap::fromImage(img));
        }
    }
}

