static void check_arguments(int argc, char* argv[])
{
  cout << "Fuck you" << endl;
  if (argc != 3){
    cout << "Please set arguments like below\n'rosrun data_preprocessor get_PCD save_dir topic_name'\n";
    exit(EXIT_FAILURE);
  }
}

void SavePCD::save_pcd(const sensor_msgs::PointCloud2::ConstPtr& msg)
{
  stringstream ss;
  ss << msg->header.stamp;
  string file_name = save_path_ + ss.str() + ".pcd";
  pcl::PointCloud<pcl::PointXYZ> points;
  pcl::fromROSMsg(*msg, points);
  pcl::io::savePCDFileASCII(file_name, points);
}

void SavePCD::sub_pcd(int argc, char* argv[])
{
  ros::init(argc, argv, "PCD_Subscriber");
  ros::NodeHandle n;
  ros::Subscriber sub = n.subscribe(topic_name_, 1, &SavePCD::save_pcd, this);
  ros::spin();
}

int main(int argc, char* argv[])
{
  check_arguments(argc, argv);
  SavePCD si;
  string path = argv[1];
  if (path[path.size() - 1] == '/'){
    path.erase(path.begin() + path.size()-1);
  }
  si.save_path_ = path + '/';
  si.topic_name_ = argv[2];
  si.sub_pcd(argc, argv);
  cout << "finish\n";
  return 0;

void obj_person__image_obj_callback(const autoware_msgs::image_obj::ConstPtr& image_obj_msg) {
    if (obj_person__image_obj_flag) {
        obj_person__image_obj_flag = false;
        obj_car__image_obj_flag = false;
        points_image_flag = false;
        vscan_image_flag = false;
        return;
    }

    obj_person__image_obj_flag = true;
    if ((points_image_flag || vscan_image_flag) && obj_car__image_obj_flag) {
        ROS_INFO("catch publish request");
        if(!publish()) {
            /* when to publish is failure, republish */
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = 200000000; //5Hz
            while (!publish() || ros::ok())
                nanosleep(&sleep_time, NULL);
        }
        obj_person__image_obj_flag = false;
        obj_car__image_obj_flag = false;
        points_image_flag = false;
        vscan_image_flag = false;
    }
}

