	for(unsigned int j = 0 ; j < quarters.size(); j++)
	{

		WayPoint wp;
		int nPoints = quarters.at(j).GetMaxPoint(wp);
		if(nPoints >= MIN_POINTS_PER_QUARTER)
		{
			polygon.push_back(wp.pos);

