    visualization_msgs::Marker marker = createAreaMarker("cross_walk", id++, Color::BLUE, vmap, area);
    if (isValidMarker(marker))
    {
      marker.scale.x = 0.4;
      marker.color.a = 0.4;
      marker_array_buffer.markers.push_back(marker);
    }
  }
}

