case 708:
	return "CUDA_ERROR_PRIMARY_CONTEXT_ACTIVE";
case 709:
	return "CUDA_ERROR_CONTEXT_IS_DESTROYED";
case 999:
	return "CUDA_ERROR_UNKNOWN";

    ROS_INFO("wait until shutdown a thread");
    pthread_kill(th, SIGINT);
    pthread_join(th, NULL);

    return 0;
}



