    //obj_label is empty
    if (obj_label_ringbuf.begin() == obj_label_ringbuf.end()) {

static void check_arguments(int argc, char* argv[])
{
  if (argc != 5){
    cout << "Please set arguments like below\n'rosrun data_preprocessor get_PCD save_dir topic_name'\n";
    exit(EXIT_FAILURE);
  }
}

