void updatePoint(std::map<Key<Point>, Point>& map, const PointArray& msg)
{
  map = std::map<Key<Point>, Point>();
  for (const auto& item : msg.data)
  {
    if (item.pid == 0)
      continue;
    map.insert(std::make_pair(Key<Point>(item.pid), item));
  }
}

